import {campuses,servicesFor,positionsFor,roleFor,positionName,statusFor,candidates,validate,autoAssign,nextSunday,sampleData} from './core.js';
import {configured,connect,db,rpc,loadDay,uploadPhoto,photoUrl,checkSetup} from './api.js';
const paths={edit:'<path d="m16 3 5 5L8 21H3v-5L16 3Zm-2 2 5 5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5 2 2 4-4"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',camera:'<path d="M14 9l7-4v14l-7-4"/><rect x="2" y="6" width="12" height="12" rx="2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',minus:'<path d="M6 12h12"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let services=servicesFor('kompally');
const date=nextSunday(),sample=sampleData(date);
const state={campus:'kompally',view:configured?'login':'availability',date,service:'first',cameraCount:8,members:configured?[]:sample.members,rows:configured?[]:sample.rows,me:configured?null:sample.members[0],demo:!configured,search:'',filterService:'all',filterStatus:'all',filterRole:'all',schedules:[],assignments:{},dirty:false,profileDirty:false,mineDirty:false,busy:false,errors:[],loadError:'',loading:configured,published:[]};
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let toastTimer,refreshSequence=0,autoSaveTimer,profileSaveTimer,mineSaveTimer;
const displayDate=()=>new Date(`${state.date}T12:00:00`).toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
const serviceName=()=>services.find(s=>s.id===state.service).name;
const initials=m=>(m.full_name||'Member').split(' ').map(s=>s[0]).join('').slice(0,2).toUpperCase();
const avatar=m=>`<span class="avatar">${m.photo?`<img src="${esc(m.photo)}" alt="" loading="lazy">`:esc(initials(m))}</span>`;
const skillName=s=>s==='ccu'?'CCU':s[0].toUpperCase()+s.slice(1);
const person=m=>`<div class="person">${avatar(m)}<div><div class="person-name">${esc(m.full_name||'New member')}</div><div class="person-skills">${m.skills.map(skillName).join(' · ')||'No skills assigned'}</div></div></div>`;
const badge=s=>`<span class="status ${s}" title="${{available:'Available',not_available:'Not Available',not_submitted:'Not Submitted'}[s]}" aria-label="${{available:'Available',not_available:'Not Available',not_submitted:'Not Submitted'}[s]}">${icon(s==='available'?'check':s==='not_available'?'minus':'clock')}</span>`;
const campusName=()=>campuses.find(c=>c.id===state.campus).name;
const campusTabs=()=>'<nav class="campus-tabs" aria-label="Select campus">'+campuses.map(c=>`<button type="button" data-campus="${c.id}" aria-pressed="${state.campus===c.id}"><span>${c.name}</span><small>Campus</small></button>`).join('')+'</nav>';
const dateControl=()=>`<label class="date-control">${icon('calendar')}<input type="date" id="service-date" aria-label="Service date" value="${state.date}"></label>`;
const currentSchedule=()=>state.schedules.find(s=>s.service_date===state.date&&s.service_id===state.service);
const demoNotice=()=>state.demo?'<div class="notice"><strong>Sample workspace.</strong> Explore with example members. Changes last for this visit only; connect Supabase to enable real accounts and saving.</div>':'';
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',6500);}
function modal(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button aria-label="Close dialog" id="close-dialog">×</button></div><div class="dialog-body">${body}</div>`;document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.setAttribute('aria-labelledby','dialog-title');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function confirmAction(title,text,action){modal(title,`<p style="line-height:1.7">${esc(text)}</p><div class="actions"><button class="btn" id="cancel-action">Cancel</button><button class="btn primary" id="confirm-action">Continue</button></div>`);document.querySelector('#cancel-action').onclick=()=>dialog.close();document.querySelector('#confirm-action').onclick=()=>{dialog.close();action();};}
function openMobileMenu(){const entries=[...document.querySelectorAll('.sidebar .nav [data-nav]')];modal('NLAG Video Team Schedule',`<nav class="mobile-nav" aria-label="Mobile navigation">${entries.map(b=>`<button class="btn ${b.classList.contains('active')?'active':''}" data-mobile-nav="${b.dataset.nav}" ${b.classList.contains('active')?'aria-current="page"':''}>${b.innerHTML}</button>`).join('')}</nav>${state.me?`<div class="mobile-account"><div class="mobile-account-details"><strong>${esc(state.me.full_name||'New member')}</strong><p class="small muted">${state.me.is_admin?'Administrator':'Team member'}</p></div>${!state.demo?'<button class="btn" id="mobile-signout">Sign out</button>':''}</div>`:''}`);dialog.querySelectorAll('[data-mobile-nav]').forEach(b=>b.onclick=()=>{const view=b.dataset.mobileNav;dialog.close();safeNavigate(()=>{state.view=view;syncAssignments();render();const heading=document.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus();}});});const signout=dialog.querySelector('#mobile-signout');if(signout)signout.onclick=()=>{dialog.close();action('signout');};}
async function flushAutoSave(){clearTimeout(autoSaveTimer);clearTimeout(profileSaveTimer);clearTimeout(mineSaveTimer);if(state.dirty&&!state.busy&&state.me?.is_admin)await saveSchedule(false,true);const pf=document.querySelector('#profile-form');if(state.profileDirty&&!state.busy&&pf)await saveProfile(new FormData(pf),true);const av=document.querySelector('#availability-form');if(state.mineDirty&&!state.busy&&av)await submitAvailability([...new FormData(av).getAll('services')],true);}
async function safeNavigate(action){const proceed=async()=>{await flushAutoSave();if(state.busy||state.dirty||state.profileDirty||state.mineDirty){toast('Please finish saving your changes before switching pages.');return;}await action();};if(state.dirty||state.profileDirty||state.mineDirty){confirmAction('Save changes before leaving?','Your latest changes will be saved automatically before you continue.',()=>{proceed();});}else await proceed();}
function syncAssignments(){state.cameraCount=currentSchedule()?.camera_count??8;state.assignments={...(currentSchedule()?.assignments||{})};state.dirty=false;state.errors=[];}
function shell(body){const isAdmin=state.me?.is_admin;const nav=state.me?[...(isAdmin?[['availability','grid','Availability']]:[]),['schedule','calendar','Service schedule'],['mine','check','My availability'],...(isAdmin?[['team','users','Team members']]:[]),['profile','user','My profile']]:[['login','user','Sign in']];const m=state.me;app.innerHTML=`<div class="layout"><aside class="sidebar"><button class="brand" data-home aria-label="Open dashboard"><img src="nlag-logo.png" alt=""><span class="brand-copy"><strong>NLAG Video Team Schedule</strong><small>New Life Assembly of God</small></span></button><div class="workspace eyebrow">${isAdmin?'Team workspace':'Member workspace'}</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,i,t])=>`<button data-nav="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="side-note"><strong>A place for everyone.</strong>Plan together. Serve with purpose.</div>${m?`<div class="account"><button class="avatar-link" data-nav="profile" aria-label="Open your profile">${avatar(m)}</button><div><strong class="small">${esc(m.full_name||'New member')}</strong><small>${isAdmin?'Administrator':'Team member'}</small>${!state.demo?'<button class="signout" data-action="signout">Sign out</button>':''}</div></div>`:''}</aside><main class="main"><header class="topbar"><button class="menu-toggle" id="open-menu" aria-label="Open navigation" aria-haspopup="dialog" aria-controls="dialog"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><div class="breadcrumb">Workspace ${icon('chevron')} <b>${nav.find(n=>n[0]===state.view)?.[2]||'Welcome'}</b></div><button class="mobile-brand" data-home aria-label="Open dashboard"><img src="nlag-logo.png" alt=""><span class="brand-copy"><strong>NLAG Video Team Schedule</strong><small>New Life Assembly of God</small></span></button><div class="top-right"><span class="pill ${state.demo?'demo':''}">${state.demo?'Sample workspace':m?'Connected':'Welcome'}</span>${m?`<button class="avatar-link" data-nav="profile" aria-label="Open your profile">${avatar(m)}</button>`:''}</div></header><div class="content">${state.me&&['availability','mine','schedule'].includes(state.view)?campusTabs():''}${body}</div></main>${m?`<nav class="mobile-bottom-nav ${isAdmin?'admin-bottom-nav':''}" aria-label="Quick navigation">${(isAdmin?nav:[['mine','check','My availability'],['schedule','calendar','Service schedule'],['profile','user','My profile']]).map(([id,i,t])=>`<button data-nav="${id}" ${state.view===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`:''}</div>`;bind();}
function availability(){const active=state.members.filter(m=>m.active),submitted=active.filter(m=>services.every(s=>statusFor(state.rows,m.id,state.date,s.id)!=='not_submitted')).length;return `<div class="page-heading"><div><h1>Team availability</h1><p>The right people, ready for every service.</p></div>${dateControl()}</div>${demoNotice()}<div class="stats">${[['Team members',active.length,'Active in your team','users'],['Responses received',submitted,`${Math.round(submitted/(active.length||1)*100)}% of your team has responded`,'check'],['Awaiting response',active.length-submitted,'Availability not submitted','clock'],['Services this day',services.length,campusName()+' campus','calendar']].map(([t,n,f,i])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><div class="stat-value">${n}<span>${t==='Responses received'?`/ ${active.length}`:''}</span></div><div class="stat-foot ${t==='Responses received'?'good':''}">${f}</div></div>`).join('')}</div><section class="panel"><div class="panel-heading"><div><h2>Availability overview</h2><p>${displayDate()}</p></div><button class="btn" data-nav="schedule">Plan service ${icon('calendar')}</button></div><div class="toolbar"><div class="search">${icon('search')}<input class="input" id="search-members" value="${esc(state.search)}" placeholder="Search team members" aria-label="Search team members"></div><div class="filters">${select('filterService',[['all','All services'],...services.map(s=>[s.id,s.name])])}${select('filterStatus',[['all','All statuses'],['available','Available'],['not_available','Not Available'],['not_submitted','Not Submitted']])}${select('filterRole',[['all','All roles'],['camera','Camera'],['producer','Producer'],['ccu','CCU']])}</div></div><div class="table-scroll" tabindex="0" role="region" aria-label="Team availability by service; scroll horizontally to see all services"><table><thead><tr><th>TEAM MEMBER</th>${services.map(s=>`<th>${s.name.toUpperCase()}</th>`).join('')}</tr></thead><tbody id="availability-rows">${availabilityRows()}</tbody></table></div><div class="legend"><span>${badge('available')} Available</span><span>${badge('not_available')} Not Available</span><span>${badge('not_submitted')} Not Submitted</span></div></section><div class="below-note"><span>Availability is submitted by team members.</span><span>Duty assignments are chosen by your admin.</span></div>`;}
function select(id,options){return `<select id="${id}" aria-label="${id==='filterRole'?'Filter role':id==='filterStatus'?'Filter availability status':'Filter service'}">${options.map(([v,t])=>`<option value="${v}" ${state[id]===v?'selected':''}>${t}</option>`).join('')}</select>`;}
function filteredMembers(){return state.members.filter(m=>m.active&&m.full_name.toLowerCase().includes(state.search.toLowerCase())&&(state.filterRole==='all'||m.skills.includes(state.filterRole))&&(state.filterStatus==='all'||services.filter(s=>state.filterService==='all'||s.id===state.filterService).some(s=>statusFor(state.rows,m.id,state.date,s.id)===state.filterStatus)));}
function availabilityRows(){return filteredMembers().map(m=>`<tr><td>${person(m)}</td>${services.map(s=>`<td>${badge(statusFor(state.rows,m.id,state.date,s.id))}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">No members match these filters.</div></td></tr>';}
const tabs=()=>`<div class="service-tabs" aria-label="Select service">${services.map(s=>`<button data-service="${s.id}" class="${state.service===s.id?'active':''}" aria-pressed="${state.service===s.id}">${s.name}</button>`).join('')}</div>`;
function schedule(){const positions=positionsFor(state.cameraCount);const admin=state.me.is_admin;const available=state.members.filter(m=>m.active&&statusFor(state.rows,m.id,state.date,state.service)==='available');const saved=currentSchedule();const filled=Object.values(state.assignments).filter(Boolean).length;const card=p=>{const m=state.members.find(m=>m.id===state.assignments[p]);return `<button class="duty ${m?'':'empty'}" data-position="${p}" aria-label="Assign ${positionName(p)}${m?`, currently ${esc(m.full_name)}`:''}"><div class="duty-title">${positionName(p)} ${icon(p.startsWith('cam')?'camera':p==='producer'?'users':'grid')}</div>${m?person(m):'<div class="placeholder"><span class="add">+</span>Assign a member</div>'}</button>`;};return `<div class="page-heading"><div><h1>Service schedule</h1><p>${admin?'Turn availability into a team ready to serve.':'See who is serving at each service.'}</p></div>${dateControl()}</div>${demoNotice()}${tabs()}${admin?`<div class="assignment-layout"><section><div class="section-label"><h2>${serviceName()} <span class="draft-badge ${saved?.status==='published'&&!state.dirty?'published':''}">${state.dirty?'Unsaved changes':saved?.status==='published'?'Published':'Draft'}</span></h2><small>${filled} of ${positions.length} positions filled</small></div><div class="progress-track"><div style="width:${filled/positions.length*100}%"></div></div><div class="section-label"><h3>Service leadership</h3><small>Producer & control</small></div><div class="duty-grid">${positions.slice(0,2).map(card).join('')}</div><div class="section-label"><h3>Camera team</h3><label class="camera-count-label">Number of cameras <select id="camera-count" aria-label="Number of cameras">${Array.from({length:17},(_,n)=>`<option value="${n}" ${n===state.cameraCount?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="duty-grid cameras">${positions.slice(2).map(card).join('')||'<p class="small muted">No camera duties for this service.</p>'}</div>${state.errors.length?`<div class="error-list" role="alert"><strong>Please resolve before publishing</strong><ul>${state.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<div class="actions"><button class="btn" data-action="auto">${icon('spark')} Auto Assign</button><button class="btn" data-action="save">Save Draft</button><button class="btn" data-action="validate">Validate</button><button class="btn primary" data-action="publish">Publish</button></div>${saved?.status==='published'&&!state.dirty?'<div class="actions"><button class="btn" data-action="whatsapp">Generate WhatsApp Schedule</button></div>':''}<p class="small muted" style="margin-top:18px;line-height:1.6">Only active, available members with the required skill can be assigned. Each member holds one duty per service.</p></section><aside class="panel roster"><div class="panel-heading"><div><h2>Available team</h2><p>${available.length} members · ${serviceName()}</p></div></div>${available.map(person).join('')||'<div class="empty-state">No availability yet.</div>'}</aside></div>`:publishedSchedule()}`;}
function publishedSchedule(){const positions=positionsFor(currentSchedule()?.camera_count??8);const list=state.published.filter(a=>a.service_id===state.service);return `<section class="panel"><div class="panel-heading"><h2>${serviceName()}</h2><span class="draft-badge ${list.length?'published':''}">${list.length?'Published':'Not published'}</span></div>${list.length?`<div class="form-grid">${positions.map(p=>{const a=list.find(a=>a.position===p);return `<div><p class="small muted">${positionName(p)}</p><h3 style="margin-top:8px">${esc(a?.full_name||'Unassigned')}${a?.user_id===state.me.id?' · You':''}</h3></div>`;}).join('')}</div>`:'<div class="empty-state"><h2>Your schedule is on its way</h2>Your admin will publish the final team here.</div>'}</section>`;}
function mine(){const submitted=services.every(s=>statusFor(state.rows,state.me.id,state.date,s.id)!=='not_submitted');return `<div class="page-heading"><div><h1>My availability</h1><p>Choose the services you can be part of.</p></div>${dateControl()}</div>${demoNotice()}<div class="narrow"><form class="panel" id="availability-form"><div class="panel-heading"><div><h2>${displayDate()}</h2><p>Choose services. Your admin will assign your duty.</p></div><span class="draft-badge ${submitted?'published':''}">${submitted?'Submitted':'Not Submitted'}</span></div><div class="availability-options">${services.map(s=>{const status=statusFor(state.rows,state.me.id,state.date,s.id);return `<label class="service-choice"><input type="checkbox" name="services" value="${s.id}" ${status==='available'?'checked':''}><span><strong>${s.name}</strong><small>${status==='not_submitted'?'Not submitted yet':status==='available'?'You are available':'You are not available'}</small></span></label>`;}).join('')}</div><div class="panel-footer"><p class="small muted">Unchecked services will be marked Not Available.</p><button class="btn primary" ${!state.me.active?'disabled':''}>${submitted?'Update':'Submit'} Availability</button></div></form><p class="small muted" style="margin-top:18px;line-height:1.7">Being available makes you eligible for assignment. Your final duty will appear in the published service schedule.</p>${!state.me.active?'<div class="notice" style="margin-top:18px">Your account is inactive. Contact your team admin.</div>':''}</div>`;}
function profile(){const m=state.me;return `<div class="page-heading profile-page-heading"><div><h1>My profile</h1><p>A little about the person behind the service.</p></div></div>${demoNotice()}<form class="panel narrow profile-sheet" id="profile-form"><section class="profile-mobile-hero" aria-label="Your profile"><div class="profile-hero-content"><div class="profile-photo-wrap">${avatar(m)}<label for="profile-photo" class="profile-photo-trigger" aria-label="Change profile photo" tabindex="0">${icon('edit')}</label></div><div class="profile-identity"><h1>${esc(m.full_name||'New member')}</h1><p>${m.skills.map(skillName).join(' · ')||'Team member'}</p><span class="profile-status ${m.active?'':'inactive'}">${m.active?'Active member':'Inactive member'}</span></div></div><span class="profile-motto">For His glory</span></section><div class="profile-mobile-stats"><div>${icon('camera')}<span><strong>${m.skills.length}</strong><small>Roles</small></span></div><div>${icon('check')}<span><strong>${m.active?'Active':'Inactive'}</strong><small>Team member</small></span></div><div>${icon('users')}<span><strong>NLAG</strong><small>Video team</small></span></div></div><div class="panel-heading profile-desktop-heading">${person(m)}<span class="draft-badge">${m.active?'Active member':'Inactive member'}</span></div><section class="profile-personal"><div class="profile-section-heading"><span class="profile-section-icon">${icon('user')}</span><div><h2>Personal Information</h2><p>Your basic account details</p></div><button type="button" class="profile-edit" id="profile-edit">Edit</button></div><div class="form-grid"><label class="field">Full name<input class="input" name="full_name" value="${esc(m.full_name)}" required maxlength="100" autocomplete="name"></label><label class="field">Phone<input class="input" type="tel" name="phone" value="${esc(m.phone)}" maxlength="30" autocomplete="tel" required></label><label class="field full">Email<input class="input" value="${esc(m.email)}" disabled></label><label class="field full profile-upload">Profile photo<input id="profile-photo" class="input" type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG, or WebP. Maximum 2 MB.</small></label></div></section><div class="profile-side"><section class="profile-skills"><div class="profile-section-heading"><span class="profile-section-icon">${icon('users')}</span><div><h2>Skills / Roles</h2><p>Roles assigned by the admin</p></div><span class="profile-admin-badge">Admin managed</span></div><div class="profile-role-list">${m.skills.map(s=>`<span class="tag profile-role role-${esc(s)}">${icon(s==='camera'?'camera':s==='producer'?'users':'grid')}${esc(skillName(s))}</span>`).join(' ')||'<span class="muted">No skills assigned yet</span>'}</div></section><div class="field full profile-user-id"><span class="muted small">User ID: ${esc(m.id)}</span></div><div class="panel-footer profile-actions"><span class="small muted">Your profile is linked to your account.</span><button class="btn primary">Save profile</button>${!state.demo?'<button type="button" class="btn profile-signout" data-action="signout">Sign out</button>':''}</div></div></form>`;}
function team(){const active=state.members.filter(m=>m.active),previous=state.members.filter(m=>!m.active);const card=(m,old)=>`<article class="panel member-card">${person(m)}<p class="small muted" style="overflow-wrap:anywhere">${esc(m.email)}</p><p class="small muted" style="margin-top:6px">${esc(m.phone||'Phone not added')}</p><div class="tags">${m.skills.map(s=>`<span class="tag">${skillName(s)}</span>`).join('')}<span class="tag">${m.active?'Active':'Previous member'}</span></div><div class="member-actions"><button class="btn" data-member="${m.id}">Manage skills & status</button><button class="btn ${old?'lime':'danger'}" data-member-${old?'restore':'remove'}="${m.id}">${old?'Restore member':'Delete member'}</button></div></article>`;return `<div class="page-heading"><div><h1>Team members</h1><p>Skills, people, and a place to serve.</p></div><span class="pill">${active.length} active members</span></div>${demoNotice()}<section class="team-section"><div class="section-label"><h2>Current team</h2><small>Active members can share availability and receive assignments.</small></div><div class="team-cards">${active.map(m=>card(m,false)).join('')||'<section class="panel empty-state">No active members yet.</section>'}</div></section>${previous.length?`<section class="team-section previous-members"><div class="section-label"><h2>Previous team members</h2><small>Deleted members are kept here so past schedules remain understandable.</small></div><div class="team-cards">${previous.map(m=>card(m,true)).join('')}</div></section>`:''}`;}
function login(){const register=state.view==='register';return `<main class="welcome-page ${register?'welcome-register':'welcome-login'}"><section class="welcome-story" aria-label="Welcome to NLAG Video Team Schedule"><div class="welcome-orbit" aria-hidden="true"></div><header class="welcome-header"><button class="welcome-brand" data-auth="login" aria-label="NLAG Video Team Schedule home"><img src="nlag-logo.png" alt=""><span>NLAG<span class="welcome-brand-sub">Video Team Schedule</span></span></button><span class="welcome-ministry">NEW LIFE ASSEMBLY OF GOD</span></header><div class="welcome-message"><span class="welcome-kicker"><span aria-hidden="true"></span> ONE TEAM. ONE PURPOSE.</span><h1>Behind every frame.<br><em>A greater purpose.</em></h1><p class="welcome-intro">Your creativity has a calling. Welcome to the team that brings faith into focus.</p><div class="scripture-card"><span class="scripture-label">A WORD FOR YOUR SERVICE</span><blockquote>“And whatsoever ye do, do it heartily, as to the Lord, and not unto men;”</blockquote><cite>Colossians 3:23 <span>· KJV</span></cite></div></div><footer class="welcome-story-footer"><span>Called to create.<br><strong>Connected to serve.</strong></span><span class="welcome-cross" aria-hidden="true"></span></footer></section><section class="welcome-access" aria-labelledby="welcome-form-title"><div class="welcome-form-wrap"><div class="welcome-form-top"><span class="welcome-step">${register?'YOUR NEXT CHAPTER':'YOUR TEAM IS HERE'}</span><span class="welcome-dot" aria-hidden="true"></span></div><h2 id="welcome-form-title">${register?'There’s a place <br>for you here.':'Welcome back, <br><span class="welcome-team">team.</span>'}</h2><p class="welcome-form-intro">${register?'Bring your gifts. Join the NLAG media family and be part of something meaningful.':'Ready to make a difference? Sign in to plan, connect, and serve together.'}</p><form id="auth-form" class="welcome-form">${register?'<label class="field">Full name<input class="input" name="full_name" placeholder="Your full name" required autocomplete="name" maxlength="100"></label>':''}<label class="field">Email address<input class="input" name="email" type="email" placeholder="you@example.com" required autocomplete="email"></label><label class="field">Password<input class="input" name="password" type="password" placeholder="${register?'Create a password':'Enter your password'}" required ${register?'minlength="12" aria-describedby="password-guide"':''} autocomplete="${register?'new-password':'current-password'}"></label>${register?'<p class="welcome-password-guide" id="password-guide">Use at least 12 characters.</p>':''}<button class="btn primary welcome-submit">${register?'Join the team':'Sign in to Video Team Schedule'}<span aria-hidden="true">↗</span></button></form><div class="welcome-switch"><span>${register?'Already part of the team?':'New to the media family?'}</span><button type="button" data-auth="${register?'login':'register'}">${register?'Sign in':'Create your account'} <span aria-hidden="true">→</span></button></div><div class="welcome-blessing"><span aria-hidden="true">✦</span><p>May the work of your hands<br>bring light to someone’s life.</p></div></div><footer class="welcome-access-footer">NLAG Video Team Schedule <span>Made for ministry.</span></footer></section><div class="welcome-purpose" aria-hidden="true"><div><span>Capture</span><span>Create</span><span>Share</span><span>Serve</span></div><p>FOR HIS GLORY</p></div></main>`;}
function render(){if(state.loading){shell('<div class="empty-state"><h2>Loading your workspace…</h2></div>');return;}if(state.loadError){shell(`<div class="error-list" role="alert"><strong>Unable to load your workspace</strong><p>${esc(state.loadError)}</p><button class="btn" data-action="retry">Try again</button></div>`);return;}if(['login','register'].includes(state.view)){app.innerHTML=login();bind();}else shell((({availability,schedule,mine,profile,team,login,register:login})[state.view]||login)());if(state.busy)app.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);}
function bind(){document.querySelectorAll('[data-campus]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.campus=b.dataset.campus;services=servicesFor(state.campus);state.service=services[0].id;state.filterService='all';syncAssignments();render();}));const editProfile=document.querySelector("#profile-edit");if(editProfile)editProfile.onclick=()=>{const input=document.querySelector('#profile-form [name="full_name"]');input?.focus();input?.select();};const photoTrigger=document.querySelector(".profile-photo-trigger");if(photoTrigger)photoTrigger.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();document.querySelector("#profile-photo")?.click();}};const menuButton=document.querySelector("#open-menu");if(menuButton)menuButton.onclick=openMobileMenu;document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.view=state.me?.is_admin?'availability':'schedule';syncAssignments();render();}));const countInput=document.querySelector('#camera-count');if(countInput)countInput.onchange=()=>{const count=Number(countInput.value);countInput.value=String(state.cameraCount);const keep=positionsFor(count);const removed=Object.keys(state.assignments).filter(p=>!keep.includes(p));const apply=()=>{state.cameraCount=count;state.assignments=Object.fromEntries(Object.entries(state.assignments).filter(([p])=>keep.includes(p)));state.dirty=true;state.errors=[];render();scheduleAutoSave();};if(removed.length)confirmAction('Remove camera assignments?', 'Reducing the camera count will clear '+removed.map(positionName).join(', ')+'. Save or publish to store this change.',apply);else apply();};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.view=b.dataset.nav;syncAssignments();render();}));document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.service=b.dataset.service;syncAssignments();render();}));const dateInput=document.querySelector('#service-date');if(dateInput)dateInput.onchange=()=>{const value=dateInput.value;dateInput.value=state.date;if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return;safeNavigate(async()=>{state.date=value;state.loading=!state.demo;render();await refresh();syncAssignments();render();});};
 const search=document.querySelector('#search-members');if(search)search.oninput=()=>{state.search=search.value;document.querySelector('#availability-rows').innerHTML=availabilityRows();};for(const id of ['filterService','filterRole','filterStatus']){const el=document.getElementById(id);if(el)el.onchange=()=>{state[id]=el.value;document.querySelector('#availability-rows').innerHTML=availabilityRows();};}
 document.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>pick(b.dataset.position));document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>editMember(b.dataset.member));document.querySelectorAll('[data-member-remove]').forEach(b=>b.onclick=()=>setMemberActive(b.dataset.memberRemove,false));document.querySelectorAll('[data-member-restore]').forEach(b=>b.onclick=()=>setMemberActive(b.dataset.memberRestore,true));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{state.view=b.dataset.auth;render();});
 const av=document.querySelector('#availability-form');if(av){av.onchange=()=>{state.mineDirty=true;queueMineAutoSave(av);};av.onsubmit=e=>{e.preventDefault();const selected=[...new FormData(av).getAll('services')];if(!state.me.full_name.trim()||!state.me.phone.trim()){toast('Complete your name and phone in My profile first.');return;}if(!selected.length)confirmAction('Unavailable for all services?',`All services at ${campusName()} will be marked Not Available.`,()=>submitAvailability(selected));else submitAvailability(selected);};}
 const pf=document.querySelector('#profile-form');if(pf){pf.oninput=e=>{state.profileDirty=true;if(e.target.type!=='file')queueProfileAutoSave(pf);};pf.onsubmit=e=>{e.preventDefault();saveProfile(new FormData(pf));};}const af=document.querySelector('#auth-form');if(af)af.onsubmit=e=>{e.preventDefault();authenticate(new FormData(af));};}
async function busy(fn){if(state.busy)return;state.busy=true;const disabled=[...app.querySelectorAll('button,input,select'),...dialog.querySelectorAll('button,input')].map(x=>[x,x.disabled]);disabled.forEach(([x])=>x.disabled=true);try{await fn();}catch(e){toast(e.message||'Something went wrong. Please try again.');}finally{state.busy=false;disabled.forEach(([x,prior])=>x.disabled=prior);if(!document.contains(disabled[0]?.[0]))render();}}
async function refresh(){if(state.demo){state.loading=false;return;}if(!state.me){state.loading=false;return;}const seq=++refreshSequence;try{const data=await loadDay(state.date);if(seq!==refreshSequence)return;Object.assign(state,data);state.me=data.members.find(m=>m.id===state.me.id)||state.me;if(!state.me.is_admin){state.published=await rpc('published_schedule',{p_date:state.date});}state.loadError='';const photos=await Promise.all(state.members.filter(m=>m.avatar_url).map(async m=>[m.id,await photoUrl(m.avatar_url)]));for(const [id,url] of photos){const m=state.members.find(m=>m.id===id);if(m)m.photo=url;}}catch(e){state.loadError=e.message;}finally{state.loading=false;}}
async function action(name){if(name==='retry'){state.loadError='';state.loading=true;render();if(state.me)await refresh();else await start();render();return;}if(name==='signout'){safeNavigate(()=>busy(async()=>{const {error}=await db.auth.signOut();if(error)throw error;state.me=null;state.members=[];state.rows=[];state.schedules=[];state.published=[];state.view='login';render();}));return;}
 if(!state.me?.is_admin)return;if(name==='auto'){const errs=validate(state.assignments,state.members,state.rows,state.date,state.service,false,state.cameraCount);if(errs.length){state.errors=errs;render();return;}state.assignments=autoAssign(state.members,state.rows,state.date,state.service,state.assignments,state.cameraCount);state.dirty=true;state.errors=[];render();scheduleAutoSave();toast('Open positions filled where eligible members are available.');}
 if(name==='validate'){state.errors=validate(state.assignments,state.members,state.rows,state.date,state.service,true,state.cameraCount);render();if(!state.errors.length)toast(`Ready to publish. All ${state.cameraCount+2} duties are valid and unique.`);}
 if(name==='save')await saveSchedule(false);if(name==='publish'){state.errors=validate(state.assignments,state.members,state.rows,state.date,state.service,true,state.cameraCount);if(state.errors.length){render();return;}confirmAction(state.demo?'Preview publishing':'Publish this service?',state.demo?'This previews a published schedule using sample data. It is not saved to a database.':`Publish ${serviceName()} for ${displayDate()} to your team?`,()=>saveSchedule(true));}if(name==='whatsapp')whatsapp();}
function pick(position){const people=candidates(state.members,state.rows,state.date,state.service,position);modal(`Assign ${positionName(position)}`,`<p class="small muted" style="margin-bottom:18px">Available for ${serviceName()} · ${displayDate()}</p>${people.map(m=>{const assigned=Object.entries(state.assignments).find(([p,id])=>id===m.id&&p!==position)?.[0];return `<button class="candidate" data-candidate="${m.id}" ${assigned?'disabled':''}>${person(m)}<small class="muted">${assigned?`Assigned to ${positionName(assigned)}`:state.assignments[position]===m.id?'Selected':'Select'}</small></button>`;}).join('')||'<div class="empty-state">No available members have this skill yet.</div>'}${state.assignments[position]?'<button class="btn" id="remove-assignment">Remove assignment</button>':''}`);dialog.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>{state.assignments[position]=b.dataset.candidate;state.dirty=true;state.errors=[];dialog.close();render();scheduleAutoSave();});const rm=document.querySelector('#remove-assignment');if(rm)rm.onclick=()=>{delete state.assignments[position];state.dirty=true;dialog.close();render();scheduleAutoSave();};}
function scheduleAutoSave(){clearTimeout(autoSaveTimer);autoSaveTimer=setTimeout(()=>{if(state.dirty&&!state.busy)saveSchedule(false,true);},250);}
function queueProfileAutoSave(form){clearTimeout(profileSaveTimer);const draft=new FormData(form);draft.delete('photo');profileSaveTimer=setTimeout(()=>{if(state.profileDirty&&!state.busy)saveProfile(draft,true);},250);}
function queueMineAutoSave(form){clearTimeout(mineSaveTimer);const selected=[...new FormData(form).getAll('services')];mineSaveTimer=setTimeout(()=>{if(state.mineDirty&&!state.busy)submitAvailability(selected,true);},250);}
async function saveSchedule(publish,automatic=false){await busy(async()=>{const errors=validate(state.assignments,state.members,state.rows,state.date,state.service,publish,state.cameraCount);if(errors.length){state.errors=errors;render();return;}const payload={camera_count:state.cameraCount,service_date:state.date,service_id:state.service,assignments:{...state.assignments},status:publish?'published':'draft',revision:(currentSchedule()?.revision||0)+1};if(state.demo){state.schedules=state.schedules.filter(s=>!(s.service_date===state.date&&s.service_id===state.service));state.schedules.push(payload);}else{await rpc('save_schedule',{p_date:state.date,p_service:state.service,p_assignments:state.assignments,p_publish:publish,p_revision:currentSchedule()?.revision||0,p_camera_count:state.cameraCount});await refresh();}state.dirty=false;state.errors=[];render();toast(automatic?'Draft saved automatically.':state.demo?`Sample ${publish?'publication':'draft'} previewed for this visit only.`:publish?'Service schedule published.':'Draft saved.');});}
async function submitAvailability(selected,automatic=false){await busy(async()=>{if(state.demo){state.rows=state.rows.filter(r=>!(r.user_id===state.me.id&&r.service_date===state.date&&services.some(s=>s.id===r.service_id)));state.rows.push(...services.map(s=>({user_id:state.me.id,service_date:state.date,service_id:s.id,status:selected.includes(s.id)?'available':'not_available'})));for(const s of state.schedules.filter(s=>s.service_date===state.date&&services.some(svc=>svc.id===s.service_id)&&!selected.includes(s.service_id))){if(Object.values(s.assignments).includes(state.me.id)){s.assignments=Object.fromEntries(Object.entries(s.assignments).filter(([,id])=>id!==state.me.id));s.status='draft';s.revision++;}}}else{await rpc('submit_campus_availability',{p_date:state.date,p_services:selected,p_campus:state.campus});await refresh();}state.mineDirty=false;if(!automatic)render();toast(automatic?'Availability saved automatically.':state.demo?'Sample availability updated for this visit only.':'Availability submitted to your team admin.');});}
async function saveProfile(form,automatic=false){await busy(async()=>{const full_name=String(form.get('full_name')).trim(),phone=String(form.get('phone')).trim();if(!full_name||!phone)throw Error('Enter your name and phone number.');let avatar_url=state.me.avatar_url;const file=form.get('photo');if(file?.size){if(state.demo){if(file.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG, or WebP under 2 MB.');state.me.photo=URL.createObjectURL(file);}else avatar_url=await uploadPhoto(state.me.id,file);}if(state.demo)Object.assign(state.me,{full_name,phone});else{await rpc('save_profile',{p_name:full_name,p_phone:phone,p_avatar:avatar_url});await refresh();}state.profileDirty=false;if(!automatic)render();toast(automatic?'Profile saved automatically.':state.demo?'Sample profile updated for this visit only.':'Profile saved.');});}
function setMemberActive(id,targetActive){const m=state.members.find(m=>m.id===id);if(!m||(!targetActive&&m.id===state.me?.id)){toast('You cannot delete your own admin account.');return;}confirmAction(targetActive?'Restore team member?':'Delete team member?',targetActive?`${m.full_name} will return to the current team.`:`${m.full_name} will be moved to Previous team members. Past schedules are preserved.`,()=>busy(async()=>{const skills=m.skills?.length?m.skills:['camera'];if(state.demo){Object.assign(m,{active:targetActive});for(const s of state.schedules){for(const [p,uid] of Object.entries(s.assignments||{})){if(uid===id&&!targetActive){delete s.assignments[p];s.status='draft';s.revision=(s.revision||0)+1;}}}}else{await rpc('manage_member',{p_user:id,p_skills:skills,p_active:targetActive});await refresh();}dialog.close();render();toast(targetActive?'Team member restored.':'Team member moved to Previous team members.');}));}
function editMember(id){const m=state.members.find(m=>m.id===id);modal(`Manage ${m.full_name}`,`<form id="member-form"><div class="field"><label>Skills / roles</label><div class="checkboxes">${['camera','producer','ccu'].map(s=>`<label><input type="checkbox" name="skills" value="${s}" ${m.skills.includes(s)?'checked':''}>${skillName(s)}</label>`).join('')}</div></div><div class="checkboxes" style="margin:24px 0"><label><input type="checkbox" name="active" ${m.active?'checked':''} ${m.id===state.me.id?'disabled':''}>Active account</label></div><p class="small muted" style="line-height:1.6">Removing a skill or deactivating a member removes affected assignments and returns those schedules to draft.</p><div class="actions"><button class="btn primary">Save member</button></div></form>`);document.querySelector('#member-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),skills=form.getAll('skills'),active=m.id===state.me.id?m.active:form.has('active');busy(async()=>{if(state.demo){Object.assign(m,{skills,active});for(const s of state.schedules){for(const [p,uid] of Object.entries(s.assignments)){if(uid===id&&(!active||!skills.includes(roleFor(p)))){delete s.assignments[p];s.status='draft';s.revision++;}}}}else{await rpc('manage_member',{p_user:id,p_skills:skills,p_active:active});await refresh();}dialog.close();render();toast(state.demo?'Sample member updated for this visit only.':'Member updated.');});};}
function whatsapp(){const s=currentSchedule();const positions=positionsFor(s?.camera_count??8);if(s?.status!=='published'||state.dirty){toast('Publish the schedule first.');return;}const text=`${state.demo?'SAMPLE SCHEDULE — NOT LIVE\n\n':''}*NLAG VIDEO TEAM SCHEDULE*\n${campusName()} Campus\n${displayDate()}\n*${serviceName()}*\n\n${positions.map(p=>`${positionName(p)}: ${state.members.find(m=>m.id===s.assignments[p])?.full_name||'Unassigned'}`).join('\n')}\n\nThank you for serving!`;modal('WhatsApp schedule',`<p class="small muted" style="margin-bottom:15px">Review and copy this schedule to your team group.</p><textarea id="schedule-text" aria-label="WhatsApp schedule text" readonly>${esc(text)}</textarea><div class="actions"><button class="btn primary" id="copy-schedule">Copy schedule</button></div>`);document.querySelector('#copy-schedule').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('Schedule copied. Ready to paste into WhatsApp.');}catch{document.querySelector('#schedule-text').select();toast('Select and copy the schedule text.');}};}
async function authenticate(form){await busy(async()=>{const args={email:String(form.get('email')),password:String(form.get('password'))};const register=state.view==='register';const result=register?await db.auth.signUp({...args,options:{data:{full_name:String(form.get('full_name'))},emailRedirectTo:location.origin}}):await db.auth.signInWithPassword(args);if(result.error)throw result.error;if(register&&!result.data.session){toast('Check your email to confirm your account, then sign in.');state.view='login';render();return;}await setSession(result.data.session);});}
async function setSession(session){if(!session){state.loading=false;state.view='login';render();return;}state.me={id:session.user.id,full_name:'',skills:[],phone:'',email:session.user.email};await refresh();state.view=state.me.is_admin?'availability':state.me.full_name&&state.me.phone?'mine':'profile';syncAssignments();render();}
async function start(){try{if(!configured){render();return;}if(!(await checkSetup())){state.loading=false;state.loadError='Your team workspace is being prepared. Registration will open when the database setup is complete.';render();return;}await connect();const {data,error}=await db.auth.getSession();if(error)throw error;await setSession(data.session);db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.me=null;state.members=[];state.rows=[];state.schedules=[];state.view='login';render();}else if(event==='SIGNED_IN'&&session?.user.id!==state.me?.id)setTimeout(()=>setSession(session),0);});}catch(e){state.loading=false;state.loadError=e.message;render();}}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushAutoSave();});window.addEventListener('pagehide',()=>{flushAutoSave();});
setInterval(async()=>{if(!state.demo&&state.me&&!state.busy&&!state.dirty&&!state.mineDirty&&!state.profileDirty&&!dialog.open&&document.visibilityState==='visible'&&['availability','schedule','team'].includes(state.view)){await refresh();if(!state.busy&&!state.dirty&&!state.mineDirty&&!state.profileDirty&&!dialog.open){syncAssignments();render();}}},15000);


window.addEventListener('beforeunload',e=>{if(state.dirty||state.mineDirty||state.profileDirty){e.preventDefault();e.returnValue='';}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_service_availability',description:'Read the selected service date and availability counts visible to this admin. Does not submit availability or assign duties.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments accepted.');if(!state.me?.is_admin)throw Error('Admin access required.');return {sample:state.demo,date:state.date,services:services.map(s=>({name:s.name,available:state.members.filter(m=>m.active&&statusFor(state.rows,m.id,state.date,s.id)==='available').length}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
render();start();
document.addEventListener('change',e=>{if(e.target?.id!=='profile-photo')return;const file=e.target.files?.[0],form=e.target.closest('#profile-form');if(!file||!form)return;if(file.size>2*1024*1024||!/^image\/(jpeg|png|webp)$/.test(file.type)){e.target.value='';toast('Choose a JPG, PNG, or WebP under 2 MB.');return;}const url=URL.createObjectURL(file),preview=form.querySelector('.profile-photo-wrap .avatar img'),avatarEl=form.querySelector('.profile-photo-wrap .avatar');if(preview)preview.src=url;else if(avatarEl)avatarEl.innerHTML='<img src="'+url+'" alt="" loading="lazy">';state.profileDirty=true;toast('Photo selected. Tap Save profile to keep it.');});
